/**
 * El control de atribución de Mapbox añade enlaces (p. ej. a openstreetmap.org / mapbox.com).
 * En móvil, un toque abre la URL en la misma pestaña y parece que la app “expulsa” al usuario.
 * Misma atribución legal: abrimos en pestaña nueva y ClaraCore queda al frente.
 */
function installMapboxAttributionLinksOpenNewTab(map) {
  const el = map.getContainer()
  const fn = (e) => {
    const a = e.target && typeof e.target.closest === 'function' && e.target.closest('a[href]')
    if (!a) return
    const h = a.getAttribute('href') || ''
    if (!h || h.charAt(0) === '#') return
    e.preventDefault()
    e.stopPropagation()
    window.open(h, '_blank', 'noopener,noreferrer')
  }
  el.addEventListener('click', fn, true)
  return () => {
    try { el.removeEventListener('click', fn, true) } catch { /* ignore */ }
  }
}

const API = API_BASE

/** Preserva negativos y cero en dimensiones/cantidad SICOE; '' o null → null. */
function sicoeNumCampoOmitNull(v) {
  if (v === '' || v == null) return null
  const n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.'))
  return Number.isFinite(n) ? n : null
}

/**
 * Plano SICOE como en Presupuesto: sin puntos naranja (GPS reporte), sin offsets falsos;
 * posición solo desde maestro pk_ids (lat/lng). Añade más IDs vía
 * VITE_SICOE_CONTRATOS_SIN_NODOS_REPORTE_GPS=3,4 — el contrato 2 va incluido por migraciones GPS.
 */
const SICOE_CONTRATOS_SIN_NODOS_REPORTE_GPS = new Set(
  (() => {
    const fromEnv = String(import.meta.env.VITE_SICOE_CONTRATOS_SIN_NODOS_REPORTE_GPS || '')
      .split(/[,;]+/)
      .map((s) => s.trim())
      .filter(Boolean)
      .map((s) => parseInt(s, 10))
      .filter((n) => !Number.isNaN(n))
    return [2, ...fromEnv]
  })()
)

/** [lng, lat] WGS84 desde fila maestro PK (misma lógica que PptoFiltroMapaPk). */
function sicoePickLngLatMaestro(row) {
  if (!row || typeof row !== 'object') return null
  const la = row.lat ?? row.latitud ?? row.latitude ?? row.Lat
  const ln = row.lng ?? row.lon ?? row.longitud ?? row.longitude ?? row.Lng ?? row.lngd
  if (la == null || ln == null) return null
  const laN = parseFloat(la)
  const lnN = parseFloat(ln)
  if (Number.isNaN(laN) || Number.isNaN(lnN)) return null
  if (laN < -90 || laN > 90 || lnN < -180 || lnN > 180) return null
  return [lnN, laN]
}

function _sicoeFeaturePkId(f) {
  const p = f?.properties
  if (!p) return ''
  return String(p.PK_ID ?? p.pk_id ?? p.Layer ?? p.layer ?? p.Name ?? '').trim()
}

/** Misma semántica que en portada SICOE: `enlace_soporte` JSON array o string suelto. */
function parseEnlacesSoporteReporte(raw) {
  if (raw == null || raw === '') return []
  try {
    const p = JSON.parse(raw)
    if (Array.isArray(p)) return p.map(String).filter(Boolean)
    return [String(p)]
  } catch {
    return [String(raw)]
  }
}

/** Texto para etiqueta en mapa: abscisas (`etiqueta`) o PK en polígonos. */
function _mapLabelPlanoFeature(f, pkidResolved) {
  const p = f?.properties
  if (!p) return String(pkidResolved || '').trim()
  const et = String(p.etiqueta ?? p.Etiqueta ?? '').trim()
  if (et) return et
  return String(pkidResolved ?? p.pk_id ?? '').trim()
}

/** Filtros separados: PK en polígonos vs abscisa en puntos (no mezclar en una sola capa). */
const _FILTER_MAPBOX_LABEL_PK = [
  'all',
  ['any', ['==', ['geometry-type'], 'Polygon'], ['==', ['geometry-type'], 'MultiPolygon']],
  ['>', ['length', ['to-string', ['get', 'pk_id']]], 0],
]

/** GeoJSON del contrato (FeatureCollection, JSON string u objeto). Siempre devuelve FeatureCollection con array features. */
function _normalizeContratoPlanoGeojson(plano) {
  if (plano == null || plano === '') return { type: 'FeatureCollection', features: [] }
  let p = plano
  if (typeof p === 'string') {
    try { p = JSON.parse(p) } catch { return { type: 'FeatureCollection', features: [] } }
  }
  if (!p || typeof p !== 'object') return { type: 'FeatureCollection', features: [] }
  let fc
  if (p.type === 'FeatureCollection' && Array.isArray(p.features)) fc = p
  else if (p.type === 'Feature' && p.geometry) fc = { type: 'FeatureCollection', features: [p] }
  else if (Array.isArray(p.features)) fc = { type: 'FeatureCollection', features: p.features }
  else return { type: 'FeatureCollection', features: [] }
  return sanitizePlanoFeatureCollection(fc)
}

function _esFeaturePlanoDibujoExterno(f) {
  const p = f?.properties
  if (!p) return false
  const layer = String(p.Layer ?? p.layer ?? '').trim().toLowerCase()
  return layer === 'dibujo externo'
}

/** Recorre árbol de coordenadas GeoJSON y emite [lng, lat] (sin arrays enormes para Math.min). */
function _forEachLngLatInGeojsonCoords(node, fn) {
  if (!Array.isArray(node)) return
  if (typeof node[0] === 'number' && typeof node[1] === 'number') {
    fn(node[0], node[1])
    return
  }
  for (let i = 0; i < node.length; i++) _forEachLngLatInGeojsonCoords(node[i], fn)
}

function _boundsFromGeometry(geom) {
  if (!geom || !geom.type) return null
  let minLng = Infinity
  let maxLng = -Infinity
  let minLat = Infinity
  let maxLat = -Infinity
  let n = 0
  const consider = (lng, lat) => {
    if (!Number.isFinite(lng) || !Number.isFinite(lat)) return
    n += 1
    if (lng < minLng) minLng = lng
    if (lng > maxLng) maxLng = lng
    if (lat < minLat) minLat = lat
    if (lat > maxLat) maxLat = lat
  }
  const walk = (g) => {
    if (!g || !g.type) return
    if (g.type === 'GeometryCollection') {
      const geoms = g.geometries || []
      for (let i = 0; i < geoms.length; i++) walk(geoms[i])
      return
    }
    if (g.coordinates) _forEachLngLatInGeojsonCoords(g.coordinates, consider)
  }
  walk(geom)
  if (!n) return null
  return { minLng, maxLng, minLat, maxLat }
}

/** BBox de todas las features (polígono, línea, punto). */
function _boundsFromFeatureCollection(fc) {
  const feats = fc?.features
  if (!Array.isArray(feats) || feats.length === 0) return null
  let minLng = Infinity
  let maxLng = -Infinity
  let minLat = Infinity
  let maxLat = -Infinity
  let any = false
  for (const f of feats) {
    const b = f?.type === 'Feature' ? _boundsFromGeometry(f.geometry) : _boundsFromGeometry(f)
    if (!b) continue
    any = true
    if (b.minLng < minLng) minLng = b.minLng
    if (b.maxLng > maxLng) maxLng = b.maxLng
    if (b.minLat < minLat) minLat = b.minLat
    if (b.maxLat > maxLat) maxLat = b.maxLat
  }
  if (!any) return null
  return { minLng, maxLng, minLat, maxLat }
}

/** Coincidencia estricta de pk_id en polígonos del plano (no puntos de abscisa). */
function sicoeFeatureCoincidePkPlano(f, wantNorm) {
  const gt = f?.geometry?.type
  if (gt !== 'Polygon' && gt !== 'MultiPolygon') return false
  const id = _sicoeFeaturePkId(f).toLowerCase().replace(/\s+/g, '')
  if (!id || !wantNorm) return false
  return id === wantNorm
}

/** BBox de polígonos cuyo pk_id coincide exactamente con el maestro (ej. 120115). */
function sicoeBoundsForPkInPlano(planoRaw, pkStr) {
  const want = String(pkStr || '').trim().toLowerCase().replace(/\s+/g, '')
  if (!want) return null
  const fc = _normalizeContratoPlanoGeojson(planoRaw)
  if (!fc?.features?.length) return null
  const matched = fc.features.filter((f) => sicoeFeatureCoincidePkPlano(f, want))
  if (!matched.length) return null
  return _boundsFromFeatureCollection({ type: 'FeatureCollection', features: matched })
}

function sicoeBoundsForPkRowInPlano(planoRaw, pkRow) {
  if (!pkRow || typeof pkRow !== 'object') return null
  const pkStr = String(pkRow.pk_id || '').trim()
  if (pkStr) {
    const b = sicoeBoundsForPkInPlano(planoRaw, pkStr)
    if (b) return b
  }
  return null
}

function sicoeCentroLngLatDesdeBounds(bounds) {
  if (!bounds) return null
  return {
    lng: (bounds.minLng + bounds.maxLng) / 2,
    lat: (bounds.minLat + bounds.maxLat) / 2,
  }
}

function sicoePkRowPorId(pkList, pkId) {
  if (pkId == null || pkId === '') return null
  const list = pkList || []
  return list.find((p) => String(p.id) === String(pkId)) || null
}

/** Solo coordenadas WGS84 guardadas en el registro (sin interpolar abscisa ni centro de PK). */
function sicoeLngLatGpsRegistro(reg) {
  const lat = reg?.coord_lat
  const lng = reg?.coord_lng
  if (lat == null || lng == null || Number.isNaN(+lat) || Number.isNaN(+lng)) return null
  return { lat: +lat, lng: +lng }
}

function _mapboxFitBoundsLngLat(map, bounds, opt = {}) {
  if (!map || !bounds) return
  let { minLng, maxLng, minLat, maxLat } = bounds
  if (minLng === maxLng) { minLng -= 1e-4; maxLng += 1e-4 }
  if (minLat === maxLat) { minLat -= 1e-4; maxLat += 1e-4 }
  const {
    padding = 40,
    bearing = 0,
    maxZoom = 17,
    minZoom,
    duration = 0,
    pitch = 0,
  } = opt
  map.fitBounds([[minLng, minLat], [maxLng, maxLat]], {
    padding,
    bearing,
    pitch,
    maxZoom,
    ...(minZoom != null ? { minZoom } : {}),
    duration,
  })
}

const POLITICAS_TEXTO_VERSION = '1.0'
