/** Número para buscar en carpeta: `foto_numero` (BD) o, si no existe, `numero_registro`. */
function strRefCarpetaFoto (reg) {
  if (!reg) return null
  const tieneFn = reg.foto_numero != null && reg.foto_numero !== ''
  const n = tieneFn ? reg.foto_numero : reg.numero_registro
  if (n == null || n === '') return null
  if (tieneFn) {
    const v = Number(n)
    return Number.isNaN(v) ? String(n) : String(v).padStart(4, '0')
  }
  return String(n)
}
function regTieneFotoNumeroEnBd (reg) {
  return reg && reg.foto_numero != null && reg.foto_numero !== ''
}

/** /next-foto, /next-grafico, /next-registro: `numero` puede ser número, [n] u objeto anidado (PostgREST). */
function sicoeNumeroDesdeNextApi(j) {
  const walk = (x) => {
    if (x == null) return null
    if (typeof x === 'number' && Number.isFinite(x)) return Math.trunc(x)
    if (typeof x === 'string' && String(x).trim() !== '') {
      const n = parseInt(String(x).trim(), 10)
      return Number.isFinite(n) ? n : null
    }
    if (Array.isArray(x) && x.length) return walk(x[0])
    if (typeof x === 'object' && x.numero != null) return walk(x.numero)
    return null
  }
  if (!j || typeof j !== 'object') return null
  for (const k of ['numero', 'siguiente_numero_foto', 'siguiente_numero_grafico', 'siguiente_numero_registro']) {
    if (j[k] != null) return walk(j[k])
  }
  return null
}

async function sicoeFetchJsonOThrow(res) {
  const txt = await res.text()
  let j = {}
  try {
    j = txt ? JSON.parse(txt) : {}
  } catch {
    j = {}
  }
  if (!res.ok) {
    const d = j?.detail
    const msg =
      typeof d === 'string'
        ? d
        : Array.isArray(d)
          ? d.map((x) => x?.msg || JSON.stringify(x)).join(', ')
          : d && typeof d === 'object'
            ? JSON.stringify(d)
            : txt || `HTTP ${res.status}`
    throw new Error(msg)
  }
  return j
}

