function getAutoTheme() {
  const hour = new Date().getHours()
  return (hour >= 7 && hour < 19) ? 'light' : 'dark'
}

/** Solo el modo oscuro “puro” usa mapa/estilos dark; claro, auto-día y descansar vista usan capa clara */
function themeIsDarkChrome(activeTheme) {
  return activeTheme === 'dark'
}

const THEME_MODE_STORAGE_KEY = 'claracore_theme_mode'
const THEME_MODES = ['light', 'auto', 'dark', 'rest']
const THEME_MODE_OPTIONS = [
  { id: 'light', icon: '☀️', label: 'Claro' },
  { id: 'auto', icon: '⚡', label: 'Auto' },
  { id: 'dark', icon: '🌙', label: 'Oscuro' },
  { id: 'rest', icon: '🌿', label: 'Descansar' },
]

function ThemeModeSelector({ t, themeMode, onTheme, style = {} }) {
  return (
    <div
      style={{
        display: 'flex',
        gap: '4px',
        background: t.bg,
        border: `1px solid ${t.border}`,
        borderRadius: '20px',
        padding: '4px',
        flexShrink: 0,
        ...style,
      }}
      role="group"
      aria-label="Tema de la interfaz"
    >
      {THEME_MODE_OPTIONS.map(({ id, icon, label }) => {
        const active = themeMode === id
        return (
          <button
            key={id}
            type="button"
            title={label}
            aria-label={label}
            aria-pressed={active}
            onClick={() => onTheme(id)}
            style={{
              background: active ? t.primary : 'transparent',
              color: active ? '#fff' : t.textMuted,
              border: 'none',
              borderRadius: '14px',
              padding: '6px 10px',
              fontSize: '1.25rem',
              lineHeight: 1,
              cursor: 'pointer',
              transition: 'all 0.2s',
              minWidth: 36,
              minHeight: 36,
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {icon}
          </button>
        )
      })}
    </div>
  )
}

function loadStoredThemeMode() {
  try {
    const m = localStorage.getItem(THEME_MODE_STORAGE_KEY)
    if (m && THEME_MODES.includes(m)) return m
  } catch { /* ignore */ }
  return 'auto'
}

function capitalize(str) {
  return str.replace(/\b\w/g, c => c.toUpperCase()).replace(/\B\w/g, c => c.toLowerCase())
}

function getToken() {
  return localStorage.getItem('cc_token') || sessionStorage.getItem('cc_token')
}

