  const fetchDashboardPkidColoresCached = useCallback(
    async (contratoId, params, setColores, opts = {}) => {
      if (!contratoId) return
      const filterKey =
        params && typeof params.toString === 'function' ? String(params.toString()) : ''
      const cacheKey = dashPkidColoresCacheKey(contratoId, filterKey)
      const cached = !opts.force ? getDashCachedPayload(cacheKey) : null
      if (cached?.data != null) {
        setColores(cached.data)
        setMiniMapaColoresLoad(false)
        return
      }
      pkidColoresFetchRef.current?.abort()
      const ac = new AbortController()
      pkidColoresFetchRef.current = ac
      setMiniMapaColoresLoad(true)
      const tok = getToken()
      const timeoutId = setTimeout(() => ac.abort(), 35000)
      try {
        const res = await fetch(
          `${API_URL}/sicoe-obra/${contratoId}/dashboard-pkid-colores?${filterKey}`,
          { headers: { Authorization: `Bearer ${tok}` }, signal: ac.signal },
        )
        if (ac.signal.aborted) return
        const data = res.ok ? await res.json().catch(() => null) : null
        if (data && typeof data === 'object') {
          setDashCachedPayload(cacheKey, data)
          setColores(data)
        }
      } catch (err) {
        if (err?.name !== 'AbortError') {
          logApiFailure('dashboard-pkid-colores', err)
        }
      } finally {
        clearTimeout(timeoutId)
        if (pkidColoresFetchRef.current === ac) {
          pkidColoresFetchRef.current = null
          setMiniMapaColoresLoad(false)
        }
      }
    },
    [API_URL],
  )

