          const tipoTxt = dashTipoEjecucionLabel(r.tipo_ejecucion ?? r.tipo ?? r.tipo_entidad)
          const fmtN = (x) => (x != null && x !== '' && Number.isFinite(Number(x)) ? String(x) : (x != null && x !== '' ? String(x) : null))
